package com.college.attendance.controller;
import com.college.attendance.dto.ComplaintRequest; import com.college.attendance.entity.*; import com.college.attendance.repo.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/academic") public class AcademicController {
 private final UserRepository users; private final TeacherRepository teachers; private final StudentRepository students; private final SubjectRepository subjects; private final AssignmentRepository assignments; private final SubmissionRepository submissions; private final FeedbackComplaintRepository complaints;
 public AcademicController(UserRepository u,TeacherRepository t,StudentRepository s,SubjectRepository sub,AssignmentRepository a,SubmissionRepository ss,FeedbackComplaintRepository c){users=u;teachers=t;students=s;subjects=sub;assignments=a;submissions=ss;complaints=c;}
 private User user(){return users.findByEmail(SecurityContextHolder.getContext().getAuthentication().getName()).orElseThrow();}
 @GetMapping("/assignments") public List<Assignment> allAssignments(){User u=user(); if(u.getRole()==Role.STUDENT){Student s=students.findByUser(u).orElseThrow();return assignments.findBySubjectIn(subjects.findBySection(s.getSection()));} Teacher t=teachers.findByUser(u).orElseThrow();return assignments.findBySubjectIn(subjects.findByTeacher(t));}
 @PostMapping("/assignments") public Assignment create(@RequestBody Assignment a){Teacher t=teachers.findByUser(user()).orElseThrow(); a.setTeacher(t); if(a.getSubject()==null)throw new RuntimeException("subject required"); return assignments.save(a);}
 @PostMapping("/assignments/{id}/submit") public Submission submit(@PathVariable Long id,@RequestBody Submission s){Student st=students.findByUser(user()).orElseThrow();s.setAssignment(assignments.findById(id).orElseThrow());s.setStudent(st);s.setSubmittedAt(LocalDateTime.now());return submissions.save(s);}
 @GetMapping("/submissions") public List<Submission> submissions(){User u=user(); if(u.getRole()==Role.STUDENT)return submissions.findByStudent(students.findByUser(u).orElseThrow()); return submissions.findAll();}
 @PostMapping("/complaints") public FeedbackComplaint complaint(@RequestBody ComplaintRequest r){return complaints.save(FeedbackComplaint.builder().raisedBy(user()).type(r.getType()).subject(r.getSubject()).message(r.getMessage()).status("OPEN").createdAt(LocalDateTime.now()).build());}
 @GetMapping("/complaints/mine") public List<FeedbackComplaint> mine(){return complaints.findByRaisedBy(user());}
 @PostMapping("/complaints/{id}/resolve") public FeedbackComplaint resolve(@PathVariable Long id,@RequestBody Map<String,String> body){FeedbackComplaint c=complaints.findById(id).orElseThrow();c.setStatus("RESOLVED");c.setResolution(body.getOrDefault("resolution","Resolved"));c.setResolvedAt(LocalDateTime.now());return complaints.save(c);}
}
